pub fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    debug_assert_eq!(dst.len(), src.len(), "dst and src must have same length");
    debug_assert_eq!(dst.len(), mask.len(), "dst and mask must have same length");

    let n = dst.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        let v = if mask[i] { src[i] } else { dst[i] };
        result.push(v);
    }

    result
}